package ws

import (
	"context"
	"encoding/json"
	"errors"
	"log/slog"
	"sync"
	"time"

	"github.com/coder/websocket"
	"golang.org/x/time/rate"

	"github.com/riorhezaharris/real-time-quiz/internal/hub"
	"github.com/riorhezaharris/real-time-quiz/internal/protocol"
	"github.com/riorhezaharris/real-time-quiz/internal/quiz"
	"github.com/riorhezaharris/real-time-quiz/internal/scoring"
)

// AI-ASSISTED (Claude Code): the connection lifecycle (reader goroutine,
// single writer goroutine draining a bounded queue, separate pinger, and
// close signalling via a once-closed channel) was generated by Claude from a
// description of the backpressure requirements. Verified with
// server_test.go (join/answer/leaderboard round trips, graceful shutdown
// sends StatusGoingAway, oversized/invalid frames) under -race, and by
// running the load generator with 1000+ clients.

// conn is one client connection. Only the read goroutine touches quizID and
// userID; the hub interacts with it solely through Enqueue and Close.
type conn struct {
	h       *Handler
	ws      *websocket.Conn
	send    chan []byte
	limiter *rate.Limiter
	log     *slog.Logger

	closeOnce   sync.Once
	closed      chan struct{}
	closeStatus websocket.StatusCode
	closeReason string

	quizID string
	userID string
}

var _ hub.Client = (*conn)(nil)

func newConn(h *Handler, ws *websocket.Conn) *conn {
	cfg := h.d.Config
	return &conn{
		h:       h,
		ws:      ws,
		send:    make(chan []byte, cfg.SendBuffer),
		limiter: rate.NewLimiter(rate.Limit(cfg.MessagesPerSecond), cfg.MessageBurst),
		log:     h.d.Log,
		closed:  make(chan struct{}),
	}
}

// Enqueue implements hub.Client. It never blocks.
func (c *conn) Enqueue(msg []byte) bool {
	select {
	case <-c.closed:
		return true // already closing; not a slow-consumer event
	default:
	}
	select {
	case c.send <- msg:
		return true
	default:
		return false
	}
}

// Close implements hub.Client.
func (c *conn) Close(reason string) {
	status := websocket.StatusNormalClosure
	switch reason {
	case "slow consumer":
		status = websocket.StatusPolicyViolation
	case "server shutting down":
		status = websocket.StatusGoingAway
	}
	c.closeWith(status, reason)
}

func (c *conn) closeWith(status websocket.StatusCode, reason string) {
	c.closeOnce.Do(func() {
		c.closeStatus, c.closeReason = status, reason
		close(c.closed)
	})
}

func (c *conn) run() {
	var wg sync.WaitGroup
	wg.Add(2)
	go func() { defer wg.Done(); c.writeLoop() }()
	go func() { defer wg.Done(); c.pingLoop() }()

	c.readLoop()
	c.closeWith(websocket.StatusNormalClosure, "")
	wg.Wait()
	if c.quizID != "" {
		c.h.d.Hub.Leave(c.quizID, c)
	}
}

// readLoop processes client messages sequentially, which preserves the order
// of a single user's answers.
func (c *conn) readLoop() {
	ctx := context.Background()
	for {
		typ, data, err := c.ws.Read(ctx)
		if err != nil {
			if s := websocket.CloseStatus(err); s == -1 {
				c.log.Debug("read ended", "userId", c.userID, "err", err)
			}
			return
		}
		if typ != websocket.MessageText {
			c.sendError("", protocol.CodeBadRequest, "text frames only")
			continue
		}
		if !c.limiter.Allow() {
			c.sendError("", protocol.CodeRateLimited, "too many messages")
			continue
		}
		c.handle(data)
	}
}

// writeLoop is the only goroutine that writes data frames.
func (c *conn) writeLoop() {
	for {
		select {
		case msg := <-c.send:
			ctx, cancel := context.WithTimeout(context.Background(), writeTimeout)
			err := c.ws.Write(ctx, websocket.MessageText, msg)
			cancel()
			if err != nil {
				c.closeWith(websocket.StatusInternalError, "write failed")
				c.ws.CloseNow()
				return
			}
		case <-c.h.stop:
			c.closeWith(websocket.StatusGoingAway, "server shutting down")
		case <-c.closed:
			// Close performs the closing handshake, which also unblocks
			// the reader. Pending messages are dropped: the client will
			// get a fresh snapshot when it re-joins.
			c.ws.Close(c.closeStatus, c.closeReason)
			return
		}
	}
}

// pingLoop detects dead peers (e.g. a phone that lost signal) that would
// otherwise hold a connection and room slot open indefinitely.
func (c *conn) pingLoop() {
	interval := c.h.d.Config.PingInterval
	if interval <= 0 {
		return
	}
	t := time.NewTicker(interval)
	defer t.Stop()
	for {
		select {
		case <-c.closed:
			return
		case <-t.C:
			ctx, cancel := context.WithTimeout(context.Background(), interval/2)
			err := c.ws.Ping(ctx)
			cancel()
			if err != nil {
				c.closeWith(websocket.StatusGoingAway, "ping timeout")
				return
			}
		}
	}
}

func (c *conn) handle(data []byte) {
	var msg protocol.ClientMessage
	if err := json.Unmarshal(data, &msg); err != nil {
		c.countIn("invalid")
		c.sendError("", protocol.CodeBadRequest, "invalid JSON")
		return
	}
	switch msg.Type {
	case protocol.TypeJoin:
		c.countIn(msg.Type)
		c.handleJoin(msg)
	case protocol.TypeAnswer:
		c.countIn(msg.Type)
		c.handleAnswer(msg)
	default:
		c.countIn("unknown")
		c.sendError(msg.RequestID, protocol.CodeBadRequest, "unknown message type")
	}
}

func (c *conn) handleJoin(msg protocol.ClientMessage) {
	if c.quizID != "" {
		c.sendError("", protocol.CodeAlreadyJoined, "connection already joined "+c.quizID)
		return
	}
	ctx, cancel := context.WithTimeout(context.Background(), opTimeout)
	defer cancel()

	name := msg.DisplayName
	if name == "" {
		name = msg.UserID
	}
	score, rank, err := c.h.d.Scoring.Join(ctx, msg.QuizID, msg.UserID, name)
	if err != nil {
		c.sendMappedError("", "join", err)
		return
	}
	q, err := c.h.d.Quizzes.Get(ctx, msg.QuizID)
	if err != nil {
		c.sendMappedError("", "join", err)
		return
	}
	top, _, err := c.h.d.Leaderboard.Top(ctx, msg.QuizID, c.h.d.Config.LeaderboardTopN)
	if err != nil {
		c.sendMappedError("", "leaderboard_top", err)
		return
	}

	c.quizID, c.userID = msg.QuizID, msg.UserID
	c.log = c.log.With("quizId", c.quizID, "userId", c.userID)

	questions := make([]protocol.Question, len(q.Questions))
	for i, qs := range q.Questions {
		questions[i] = protocol.Question{ID: qs.ID, Prompt: qs.Prompt, Options: qs.Options}
	}
	c.sendJSON(protocol.TypeJoined, protocol.Joined{
		Type: protocol.TypeJoined, QuizID: q.ID, Title: q.Title, UserID: c.userID,
		Questions: questions, Score: score, Rank: rank, Leaderboard: hub.ToProtocol(top),
	})
	// Register for broadcasts only after the Joined message is queued so it
	// is always the first message the client sees for this quiz.
	c.h.d.Hub.Join(ctx, c.quizID, c)
	c.log.Info("joined", "score", score)
}

func (c *conn) handleAnswer(msg protocol.ClientMessage) {
	if c.quizID == "" {
		c.sendError(msg.RequestID, protocol.CodeNotJoined, "join a quiz first")
		return
	}
	ctx, cancel := context.WithTimeout(context.Background(), opTimeout)
	defer cancel()

	start := time.Now()
	res, err := c.h.d.Scoring.SubmitAnswer(ctx, c.quizID, c.userID, msg.QuestionID, msg.Answer)
	c.h.d.Metrics.AnswerLatency.Observe(time.Since(start).Seconds())
	if err != nil {
		c.h.d.Metrics.Answers.WithLabelValues("error").Inc()
		c.sendMappedError(msg.RequestID, "answer", err)
		return
	}
	switch {
	case res.AlreadyAnswered:
		c.h.d.Metrics.Answers.WithLabelValues("duplicate").Inc()
	case res.Correct:
		c.h.d.Metrics.Answers.WithLabelValues("correct").Inc()
	default:
		c.h.d.Metrics.Answers.WithLabelValues("incorrect").Inc()
	}
	c.sendJSON(protocol.TypeAnswerResult, protocol.AnswerResult{
		Type: protocol.TypeAnswerResult, RequestID: msg.RequestID, QuestionID: msg.QuestionID,
		Correct: res.Correct, AlreadyAnswered: res.AlreadyAnswered, Score: res.Score, Rank: res.Rank,
	})
}

// sendMappedError translates domain errors into protocol error codes. Only
// unexpected (infrastructure) errors are logged and counted as Redis errors.
func (c *conn) sendMappedError(requestID, op string, err error) {
	switch {
	case errors.Is(err, quiz.ErrNotFound):
		c.sendError(requestID, protocol.CodeQuizNotFound, err.Error())
	case errors.Is(err, scoring.ErrUnknownQuestion):
		c.sendError(requestID, protocol.CodeUnknownQuestion, err.Error())
	case errors.Is(err, scoring.ErrInvalidID), errors.Is(err, scoring.ErrInvalidName):
		c.sendError(requestID, protocol.CodeBadRequest, err.Error())
	default:
		c.h.d.Metrics.RedisErrors.WithLabelValues(op).Inc()
		c.log.Error("operation failed", "op", op, "err", err)
		c.sendError(requestID, protocol.CodeInternal, "temporary server error, please retry")
	}
}

func (c *conn) sendError(requestID, code, message string) {
	c.sendJSON(protocol.TypeError, protocol.Error{
		Type: protocol.TypeError, RequestID: requestID, Code: code, Message: message,
	})
}

func (c *conn) sendJSON(typ string, v any) {
	b, err := json.Marshal(v)
	if err != nil {
		c.log.Error("encode message", "type", typ, "err", err)
		return
	}
	if !c.Enqueue(b) {
		c.h.d.Metrics.DroppedClients.Inc()
		c.Close("slow consumer")
		return
	}
	c.h.d.Metrics.MessagesOut.WithLabelValues(typ).Inc()
}

func (c *conn) countIn(typ string) {
	c.h.d.Metrics.MessagesIn.WithLabelValues(typ).Inc()
}
